T1="P1-M4-8.1"; T2="P1-M4-8.2"
Q=[
(T1,"RC",[1],"C","A Câmara dos Deputados e o Senado Federal, sob a direção da Mesa deste, reunir-se-ão em sessão conjunta para inaugurar a sessão legislativa e dar posse ao Presidente e ao Vice-Presidente da República eleitos.","RC art. 1º, caput, I e II.","competencia"),
(T1,"RC",[1],"E","As sessões conjuntas do Congresso Nacional realizam-se sob a direção da Mesa da Câmara dos Deputados.","RC art. 1º, caput: sob a direção da Mesa do Senado.","competencia"),
(T1,"RC",[1],"E","Têm caráter solene todas as sessões conjuntas do Congresso Nacional.","RC art. 1º, § 2º: apenas as dos incisos I, II e III e as do § 1º (homenagens e datas nacionais).","tipo"),
(T1,"RC",[1],"C","Por proposta das Mesas das duas Casas, podem ser realizadas sessões conjuntas para homenagear Chefes de Estados estrangeiros e comemorar datas nacionais.","RC art. 1º, § 1º.","iniciativa"),
(T1,"RC",[2],"C","As sessões conjuntas sem data legalmente fixada serão convocadas pelo Presidente do Senado ou seu Substituto, com prévia audiência da Mesa da Câmara dos Deputados.","RC art. 2º.","competencia"),
(T1,"RC",[3],"E","As sessões conjuntas realizam-se obrigatoriamente no Plenário do Senado Federal.","RC art. 3º: Plenário da Câmara dos Deputados, salvo escolha prévia de outro local devidamente anunciado.","competencia"),
(T2,"RC",[53],"C","Nas sessões solenes do Congresso Nacional, integram a Mesa o Presidente da Câmara e, mediante convite, o Presidente do Supremo Tribunal Federal.","RC art. 53, caput.","competencia"),
(T2,"RC",[53],"E","As sessões solenes do Congresso Nacional exigem a presença da maioria absoluta dos congressistas.","RC art. 53, p.ú.: realizam-se com qualquer número.","quorum"),
(T2,"RC",[54],"C","Nas sessões solenes do Congresso Nacional não haverá expediente.","RC art. 54, p.ú.","leitura"),
(T2,"RC",[55],"C","Nas sessões solenes, somente poderão usar da palavra um Senador e um Deputado, de preferência de partidos diferentes, previamente designados pelas respectivas Casas.","RC art. 55, caput.","quorum"),
(T2,"RC",[55],"E","Na posse do Presidente e do Vice-Presidente da República, falam dois oradores, um de cada Casa.","RC art. 55, p.ú.: na inauguração da sessão legislativa e na posse não haverá oradores.","podedeve"),
(T2,"RC",[56],"E","Nas sessões solenes, são admitidas questões de ordem apenas ao Presidente da Mesa.","RC art. 56: não serão admitidas questões de ordem.","podedeve"),
(T2,"RC",[58],"C","Na sessão de inauguração dos trabalhos, de posse da Mensagem, o Presidente manda proceder à sua leitura pelo 1º Secretário, e, finda a leitura, a sessão é encerrada.","RC arts. 58 e 59.","leitura"),
(T2,"RC",[60],"E","Para a posse do Presidente da República, o Presidente designa 3 Senadores e 3 Deputados para a comissão que recebe os empossandos.","RC art. 60: 5 Senadores e 5 Deputados (3 e 3 é a recepção de Chefe de Estado, art. 68).","quorum"),
(T2,"RC",[61],"C","Reaberta a sessão, o Presidente e o Vice-Presidente eleitos ocupam os lugares, respectivamente, à direita e à esquerda do Presidente da Mesa.","RC art. 61.","leitura"),
(T2,"RC",[62],"C","O Presidente da República eleito presta o compromisso determinado no art. 78 da Constituição, estando os presentes de pé durante o ato.","RC art. 62.","leitura"),
(T2,"RC",[65],"E","Após os compromissos, o termo de posse é lido pelo 2º Secretário e assinado apenas pelos empossados.","RC art. 65: lido pelo 1º Secretário e assinado pelos empossados e pelos membros da Mesa.","competencia"),
(T2,"RC",[66],"C","Ao Presidente da República poderá ser concedida a palavra, na solenidade de posse, para se dirigir ao Congresso Nacional e à Nação.","RC art. 66.","podedeve"),
(T2,"RC",[68],"C","Para a sessão de recepção de Chefe de Estado estrangeiro, designam-se 3 Senadores e 3 Deputados para a comissão de recepção.","RC art. 68.","quorum"),
(T2,"RC",[69],"C","Reaberta a sessão, o Chefe de Estado ocupa na Mesa o lugar à direita do Presidente, e os espectadores, exceto o Presidente, conservam-se de pé.","RC art. 69, caput e § 1º.","leitura"),
(T2,"RC",[70],"E","O visitante que quiser usar da palavra deverá fazê-lo antes dos oradores da sessão.","RC art. 70: após os oradores da sessão.","leitura"),
(T2,"RC",[85],"C","Aprovada a proposta de emenda em segundo turno, as Mesas da Câmara e do Senado, em sessão conjunta solene, promulgarão a emenda à Constituição.","RC art. 85.","competencia"),
(T2,"RC",[89],"E","A Mensagem presidencial que encaminha o projeto de lei orçamentária é recebida e lida em sessão conjunta a realizar-se dentro de 72 horas da entrega ao Presidente do Senado.","RC art. 89: dentro de 48 horas.","prazo"),
(T2,"RC",[90],"C","O projeto de lei orçamentária é apreciado por Comissão Mista, e o voto contrário da maioria dos representantes de uma das Casas importa a rejeição da matéria.","RC art. 90, caput e § 4º (ver Res. 1/2006-CN).","quorum"),
(T2,"RC",[90],"E","As deliberações da Comissão Mista iniciam-se pelos representantes do Senado Federal.","RC art. 90, § 4º: iniciam-se pelos representantes da Câmara dos Deputados.","competencia"),
(T2,"RC",[93],"C","O projeto de lei orçamentária será distribuído em avulsos eletrônicos nos 5 dias seguintes à sua leitura.","RC art. 93.","prazo"),
(T2,"RC",[99],"C","As emendas pendentes de decisão do Plenário serão discutidas e votadas em grupos, conforme tenham parecer favorável ou contrário, ressalvados os destaques.","RC art. 99.","leitura"),
(T2,"RC",[100],"E","Se a Comissão não apresentar parecer no prazo fixado, o projeto orçamentário é arquivado.","RC art. 100: o Presidente do Senado convoca sessão conjunta e designa Relator para parecer oral.","competencia"),
(T2,"RC",[102],"C","Na tramitação do projeto de lei orçamentária anual, aplicam-se, no que couber, as normas do Regimento Comum para os demais projetos de lei.","RC art. 102.","leitura"),
]
